(5258896, 765124, 102398, '<td valign="top">not quite a post-it, but I realy like this photo. :)</td>', 'not quite a post-it, but I realy like this photo. :)', '2009-02-16 10:15:06.000000', NULL, 1),
(5258922, 765603, 103142, '<td valign="top">I like this very much, but the focus seems very soft--since there''s so much movement, it would be more comfortable to look at if the focus was sharper.</td>', 'I like this very much, but the focus seems very soft--since there''s so much movement, it would be more comfortable to look at if the focus was sharper.', '2009-02-16 10:36:37.000000', NULL, 1),
(5258928, 765368, 103142, '<td valign="top">I think it would look better a little darker--seems pretty light...</td>', 'I think it would look better a little darker--seems pretty light...', '2009-02-16 10:38:17.000000', NULL, 1),
(5258931, 765475, 103142, '<td valign="top">I like the idea very much, but it wasn''t immediately obvious that  it was on fire... I''m not sure how to make the fire more obvious, perhaps letting it burn a little longer, or using a little less light (the highlight on the wall and the lower corner is washing things out a tad...)</td>', 'I like the idea very much, but it wasn''t immediately obvious that  it was on fire... I''m not sure how to make the fire more obvious, perhaps letting it burn a little longer, or using a little less light (the highlight on the wall and the lower corner is washing things out a tad...)', '2009-02-16 10:40:10.000000', NULL, 1),
(5258933, 765367, 103142, '<td valign="top">I like the shot. FYI: It was hard to read the postit because it was so light.</td>', 'I like the shot. FYI: It was hard to read the postit because it was so light.', '2009-02-16 10:44:47.000000', NULL, 1),
(5258939, 765389, 96572, '<td valign="top">This is the most creative photo in this challenge.  A lot work must have gone into this, not mentioning the artistic talent to pull this off! This is simply outstanding and truly impressive.  Congratulations!  I hope this will finish at the top as this is simply breath taking! Congratulations!</td>', 'This is the most creative photo in this challenge.  A lot work must have gone into this, not mentioning the artistic talent to pull this off! This is simply outstanding and truly impressive.  Congratulations!  I hope this will finish at the top as this is simply breath taking! Congratulations!', '2009-02-16 10:54:17.000000', NULL, 1),
(5258949, 765258, 96572, '<td valign="top">Fantastic and creative! Excellent Job!</td>', 'Fantastic and creative! Excellent Job!', '2009-02-16 11:01:41.000000', NULL, 1),
(5258950, 765243, 96572, '<td valign="top">Sharp, crisp, good lighting, good dog to sit there still! Excellent! One of my favorites!</td>', 'Sharp, crisp, good lighting, good dog to sit there still! Excellent! One of my favorites!', '2009-02-16 11:02:30.000000', NULL, 1),
(5258955, 765243, 103650, '<td valign="top">Made me smile.  Nice idea.</td>', 'Made me smile.  Nice idea.', '2009-02-16 11:06:29.000000', NULL, 1),
(5258959, 765531, 89358, '<td valign="top">LOL.  Zoolander''s Magnum!</td>', 'LOL.  Zoolander''s Magnum!', '2009-02-16 11:14:46.000000', NULL, 1),
(5258984, 765603, 102994, '<td valign="top">This looks awesome, love the colour! Why didnt I think of that!</td>', 'This looks awesome, love the colour! Why didnt I think of that!', '2009-02-16 11:43:13.000000', NULL, 1),
(5258993, 765486, 102994, '<td valign="top">All I said when I saw this, was ''WOW''<br/>I want this on my wall!</td>', 'All I said when I saw this, was ''WOW''I want this on my wall!', '2009-02-16 11:44:37.000000', NULL, 1),
(5259088, 765089, 52500, '<td valign="top">The technicals are severely lacking here, but the idea is funny and the pose/expression on the guy is really, really funny.</td>', 'The technicals are severely lacking here, but the idea is funny and the pose/expression on the guy is really, really funny.', '2009-02-16 13:27:28.000000', NULL, 1),
(5259089, 764364, 98022, '<td valign="top">Awesome post-it art. Composition, lighting, and reflection are top notch. My top pick of the challenge!</td>', 'Awesome post-it art. Composition, lighting, and reflection are top notch. My top pick of the challenge!', '2009-02-16 13:32:24.000000', NULL, 1),
(5259095, 765399, 103662, '<td valign="top">so true</td>', 'so true', '2009-02-16 13:37:28.000000', NULL, 1),
(5259102, 764455, 52500, '<td valign="top">Man, this is a ribbon winning idea that got lost in the execution.  Those flowers look great, and kudos for all of that work, but the photo is lacking.  First, your white balance seems to be pretty far off.  Everything (that should be white) is really blue.  Second, the light is really flat.  Third, and a big score dropper for me, is that the image is only 640px on the long edge.  This is Advanced, bump it up to 720.</td>', 'Man, this is a ribbon winning idea that got lost in the execution.  Those flowers look great, and kudos for all of that work, but the photo is lacking.  First, your white balance seems to be pretty far off.  Everything (that should be white) is really blue.  Second, the light is really flat.  Third, and a big score dropper for me, is that the image is only 640px on the long edge.  This is Advanced, bump it up to 720.', '2009-02-16 13:43:04.000000', NULL, 1);
